/* МЕТАНОЙА · контент уроков (команда OKO TEAM) · автогенерация из методических материалов */
window.LESSONS = {"1":{"n":1,"verse":{"text":"Бог есть любовь.","ref":"1 Ин 4:8"},"intro":"Представь самого доброго, самого сильного и самого верного Друга на свете. Сегодня мы познакомимся с Тем, Кто больше и добрее всех, — с Богом.","story":["Есть Тот, Кого нельзя увидеть глазами, как солнце за облаками, но Кто всегда рядом. Это Бог. Он не человек и не волшебник из сказки, Он — живой и настоящий, и Он был всегда, ещё до звёзд и морей.","Бог очень сильный: Он придумал бабочек, горы и радугу. Но самое главное — Он очень добрый. Как маяк светит кораблям в тумане и помогает им найти дорогу домой, так и Бог светит нам Своей любовью, чтобы мы не заблудились.","Бог знает каждого из нас по имени. Он знает, сколько у тебя веснушек и о чём ты мечтаешь перед сном. И даже когда тебе грустно или страшно, Он не отходит ни на шаг.","Люди называют Бога Отцом, потому что Он заботится о нас, как самый лучший папа. Он хочет, чтобы мы Его знали, дружили с Ним и были счастливы рядом с Ним."],"golden":"Бог есть любовь, и Он всегда рядом с тобой.","questions":["Как ты думаешь, почему Бога называют добрым Отцом?","Что в мире вокруг тебя больше всего напоминает, что Бог заботливый?","Хотел бы ты подружиться с Богом? Что бы ты Ему рассказал?"],"quiz":[{"q":"Какой Бог, о котором мы узнали?","opts":["Далёкий и злой","Любящий и добрый","Придуманный в сказке"],"answer":1},{"q":"С чем мы сравнили Божью любовь?","opts":["С маяком в тумане","С холодным ветром","С тёмной пещерой"],"answer":0},{"q":"Знает ли Бог каждого из нас?","opts":["Нет, Он всех забыл","Только взрослых","Да, знает по имени"],"answer":2}],"prayer":"Дорогой Бог, спасибо, что Ты есть и что Ты любишь меня. Помоги мне узнавать Тебя всё лучше. Аминь.","parentNote":"Поговорите с ребёнком о том, что Бог невидимый, но реальный и любящий. Спросите, где сегодня он замечал Божью заботу."},"2":{"n":2,"verse":{"text":"В начале сотворил Бог небо и землю.","ref":"Быт 1:1"},"intro":"А ты знаешь, откуда взялись небо, море и первый цветок? Сегодня узнаем, как Бог создал целый огромный мир из ничего.","story":["Сначала не было совсем ничего — ни солнца, ни звёзд, ни земли, только тьма. И тогда Бог сказал: «Да будет свет!» — и вспыхнул свет. Богу достаточно было просто сказать слово, и всё появлялось.","Бог трудился шесть дней, как добрый Мастер. Он развесил на небе солнце, луну и звёзды, наполнил моря рыбами, а небо — птицами, которые запели свою первую песню.","Потом Он покрыл землю зелёной травой, деревьями с сочными плодами и цветами всех цветов радуги. По полям побежали зайцы, слоны, котята и весёлые щенки.","Каждый раз, глядя на созданное, Бог говорил: «Это хорошо!» А на седьмой день Он отдыхал и радовался всему, что сделал. Весь этот прекрасный мир Бог подарил нам с любовью.","Когда ты смотришь на закат или гладишь пушистого котёнка, помни: это придумал для тебя Бог, как заботливый Художник, который любит Своих детей."],"golden":"Бог создал прекрасный мир с любовью — и подарил его нам.","questions":["Что в природе тебе нравится больше всего? Как думаешь, зачем Бог это создал?","Почему Бог говорил, что всё созданное «хорошо»?","Как мы можем беречь мир, который подарил нам Бог?"],"quiz":[{"q":"Как Бог создавал мир?","opts":["Своим словом","Молотком и гвоздями","Он ничего не создавал"],"answer":0},{"q":"Сколько дней Бог трудился, создавая мир?","opts":["Один день","Целый год","Шесть дней"],"answer":2},{"q":"Что говорил Бог, глядя на созданное?","opts":["«Это плохо»","«Это хорошо»","Ничего не говорил"],"answer":1}],"prayer":"Спасибо, Боже, за красивый мир: за солнце, зверей и цветы. Помоги мне беречь всё, что Ты создал. Аминь.","parentNote":"Вспомните вместе, что каждый день творения Бог называл хорошим. Предложите ребёнку назвать три вещи в природе, за которые он благодарен."},"3":{"n":3,"verse":{"text":"И создал Господь Бог человека из праха земного.","ref":"Быт 2:7"},"intro":"Кто был самым первым человеком на земле? Сегодня познакомимся с Адамом и Евой и узнаем, как сильно Бог любит людей.","story":["Когда мир был уже готов, Бог создал первого человека — Адама. Он слепил его, как из мягкой глины, и вдохнул в него жизнь. И Адам ожил, задышал и открыл глаза.","Бог поселил Адама в чудесном саду Эдем, где росли самые вкусные плоды и журчали ручейки. Адам давал имена всем животным: этот — слон, а этот — жираф.","Но Адаму было одиноко одному. Тогда Бог создал ему помощницу и подругу — Еву. Теперь они были вместе и могли гулять по саду, разговаривать и радоваться.","Бог любил Адама и Еву и приходил к ним в сад. Он просил только об одном: не есть плодов с одного особенного дерева. Так Бог учил их доверять Ему и слушаться из любви.","Даже когда люди ошиблись и ослушались, Бог не перестал их любить. Как маяк не гаснет в самую тёмную ночь, так и Божья любовь не погасла — Он обещал заботиться о людях всегда."],"golden":"Бог создал людей с любовью и любит их, даже когда они ошибаются.","questions":["Как ты думаешь, что чувствовал Адам, когда впервые открыл глаза в саду?","Почему Богу было важно, чтобы люди Ему доверяли?","Что помогает тебе слушаться, когда очень хочется сделать по-своему?"],"quiz":[{"q":"Как звали первого человека?","opts":["Ной","Адам","Авраам"],"answer":1},{"q":"Как назывался сад, где жили Адам и Ева?","opts":["Эдем","Вавилон","Ковчег"],"answer":0},{"q":"Перестал ли Бог любить людей, когда они ошиблись?","opts":["Да, перестал","Он рассердился навсегда","Нет, Он любит их всегда"],"answer":2}],"prayer":"Боже, спасибо, что Ты создал людей с любовью. Помоги мне доверять Тебе и слушаться Тебя. Аминь.","parentNote":"Обсудите, что Бог любит нас даже тогда, когда мы ошибаемся. Спросите ребёнка, легко ли слушаться и почему это важно."},"4":{"n":4,"verse":{"text":"И вспомнил Бог о Ное.","ref":"Быт 8:1"},"intro":"Что бы ты построил, если бы Бог попросил спасти всех зверей? Сегодня узнаем про доброго Ноя и его огромный корабль.","story":["Жил на земле добрый человек по имени Ной, который любил Бога и слушался Его. А вокруг люди стали злыми и забыли о добре. Бог решил омыть землю большим дождём и начать заново.","Бог сказал Ною построить огромный корабль — ковчег, чтобы спастись. Ной трудился много-много дней, стучал молотком, пилил доски и не сдавался, потому что верил Богу.","Когда ковчег был готов, к нему пришли звери — по паре каждого вида: два льва, два слона, две мышки, две голубки. Ной, его семья и все животные вошли внутрь, и Бог закрыл за ними дверь.","Сорок дней шёл дождь, и вода поднялась высоко. Но ковчег плыл, и всем внутри было тепло и безопасно. Бог хранил их, как маяк хранит корабли в бурю.","Когда дождь кончился, Бог зажёг на небе радугу и обещал: больше никогда не будет такого потопа. Радуга и сегодня напоминает нам, что Бог верен Своим обещаниям."],"golden":"Бог хранит тех, кто Ему доверяет, и всегда держит Своё слово.","questions":["Как ты думаешь, трудно ли было Ною строить ковчег так долго?","Что ты чувствуешь, когда видишь на небе радугу?","В чём тебе хочется больше доверять Богу, как доверял Ной?"],"quiz":[{"q":"Что Бог попросил построить Ноя?","opts":["Башню","Ковчег","Дом на горе"],"answer":1},{"q":"Кого Ной взял с собой на ковчег?","opts":["Только рыбок","Никого","Зверей по паре и свою семью"],"answer":2},{"q":"Какой знак Бог оставил на небе после потопа?","opts":["Радугу","Молнию","Тучу"],"answer":0}],"prayer":"Спасибо, Боже, что Ты хранишь нас, как хранил Ноя. Помоги мне доверять Тебе даже в трудные дни. Аминь.","parentNote":"Поговорите о том, что Ной доверял Богу и был терпеливым. Спросите ребёнка, что для него значит держать своё обещание."},"5":{"n":5,"verse":{"text":"Сойдём же и смешаем там язык их.","ref":"Быт 11:7"},"intro":"А что случится, если люди захотят стать выше самого Бога? Сегодня узнаем про очень высокую башню и важный урок гордости.","story":["Прошло время, и на земле снова стало много людей. Все они говорили на одном языке и понимали друг друга. Это было удобно и хорошо.","Но однажды люди задумали построить башню до самого неба, чтобы прославить самих себя и стать великими без Бога. «Мы сами всё можем!» — гордо говорили они и клали кирпич за кирпичом.","Они забыли поблагодарить Бога и вовсе перестали Его слушать. Их сердца наполнились гордостью, и они думали только о своей славе.","Тогда Бог мягко остановил их: люди вдруг заговорили на разных языках и перестали понимать друг друга. «Подай кирпич!» — а в ответ непонятные слова. Стройка остановилась, и люди разошлись по всей земле.","Эта история учит нас доброму: хорошо быть скромными и помнить о Боге. Он рад, когда мы делаем добрые дела вместе с Ним, а не хвастаемся, будто нам никто не нужен."],"golden":"Хорошо быть скромным и помнить Бога во всех своих делах.","questions":["Почему людям было плохо строить башню только ради своей славы?","Что значит быть скромным? Приведи пример из своей жизни.","Как можно делать добрые дела вместе с Богом?"],"quiz":[{"q":"Что люди хотели построить до неба?","opts":["Ковчег","Мост","Башню"],"answer":2},{"q":"Почему люди начали строить башню?","opts":["Из гордости, ради своей славы","Чтобы помочь бедным","Чтобы поблагодарить Бога"],"answer":0},{"q":"Что произошло, когда Бог остановил стройку?","opts":["Пошёл дождь","Люди заговорили на разных языках","Башня стала золотой"],"answer":1}],"prayer":"Боже, помоги мне быть скромным и помнить о Тебе во всех делах. Пусть моё сердце будет добрым, а не гордым. Аминь.","parentNote":"Обсудите разницу между хвастовством и скромностью. Спросите ребёнка, за что он может поблагодарить Бога вместо того, чтобы гордиться."},"6":{"n":6,"verse":{"text":"Непрестанно молитесь.","ref":"1 Фес 5:17"},"intro":"А знаешь ли ты, что с Богом можно разговаривать в любую минуту? Сегодня узнаем, что такое молитва — тёплый разговор с Богом.","story":["Молитва — это когда мы разговариваем с Богом. Для этого не нужен телефон и не нужно кричать. Бог слышит нас, даже когда мы шепчем или говорим в сердце.","Молиться можно где угодно: дома в кроватке, по дороге в парк, утром и вечером. Бог всегда рядом и всегда рад тебя услышать, как добрый друг рад твоему звонку.","В молитве мы можем говорить Богу спасибо за хороший день, просить о помощи, когда трудно, и рассказывать Ему свои радости и печали. Он слушает внимательно и с любовью.","Иногда мы не знаем, что сказать, — и это тоже хорошо. Можно просто побыть с Богом в тишине, как с самым близким. Он понимает даже то, что мы не можем выразить словами.","Молитва — это как лучик света к маяку: он всегда доходит. Бог слышит каждую молитву и отвечает на неё так, как лучше для нас, потому что очень нас любит."],"golden":"Молитва — это тёплый разговор с Богом, и Он всегда слышит тебя.","questions":["О чём тебе хотелось бы поговорить с Богом сегодня?","Как ты думаешь, слышит ли Бог даже тихую молитву в сердце?","За что ты можешь сказать Богу спасибо прямо сейчас?"],"quiz":[{"q":"Что такое молитва?","opts":["Волшебное заклинание","Разговор с Богом","Песенка перед сном"],"answer":1},{"q":"Где можно молиться Богу?","opts":["Только в одном месте","Нигде нельзя","Где угодно — Бог везде рядом"],"answer":2},{"q":"Слышит ли Бог наши молитвы?","opts":["Да, каждую слышит с любовью","Только громкие","Нет, Он занят"],"answer":0}],"prayer":"Дорогой Бог, спасибо, что Ты всегда слышишь меня. Научи меня говорить с Тобой каждый день. Аминь.","parentNote":"Помолитесь вместе простыми словами перед сном. Покажите ребёнку, что молиться можно своими словами, о чём угодно."},"7":{"n":7,"verse":{"text":"Ангелам Своим заповедает о тебе — охранять тебя на всех путях твоих.","ref":"Пс 90:11"},"intro":"Кто такие ангелы и правда ли, что у Бога есть добрые помощники? Сегодня узнаем про ангелов — посланников Божьих.","story":["Ангелы — это добрые помощники Бога. Они живут рядом с Ним на небе и с радостью выполняют то, что Он им поручает. Ангелы очень любят Бога и служат Ему.","Слово «ангел» значит «вестник», то есть тот, кто приносит важную новость. В Библии ангелы приносили людям добрые вести от Бога и говорили: «Не бойся!»","Ангелы охраняют людей. Бог посылает их беречь нас на всех наших путях, как заботливые невидимые стражи. Они помогают в трудную минуту, хотя мы их и не видим.","Ангелы не куклы с открыток и не волшебники. Они всегда служат доброму Богу и радуются, когда люди приходят к Нему. Они поют Богу песни хвалы на небесах.","Знать про ангелов — тепло и спокойно на сердце. Ведь это значит, что Бог заботится о нас не только Сам, но и через Своих добрых посланников, как маяк посылает свет в каждый уголок."],"golden":"Бог заботится о нас и посылает Своих добрых ангелов беречь нас.","questions":["Что означает слово «ангел» и какие новости они приносили людям?","Как ты себя чувствуешь, зная, что Бог посылает ангелов беречь тебя?","Почему ангелы так радостно служат Богу?"],"quiz":[{"q":"Кто такие ангелы?","opts":["Добрые помощники и посланники Бога","Герои мультика","Обычные птицы"],"answer":0},{"q":"Что означает слово «ангел»?","opts":["Воин","Вестник, тот, кто приносит новость","Строитель"],"answer":1},{"q":"Что часто говорили ангелы людям?","opts":["«Уходите»","«Постройте башню»","«Не бойся!»"],"answer":2}],"prayer":"Спасибо, Боже, что Ты бережёшь меня и посылаешь Своих ангелов. С Тобой мне спокойно и не страшно. Аминь.","parentNote":"Расскажите ребёнку, что ангелы служат Богу и заботятся о людях по Его воле. Подчеркните, что защита исходит от Бога."},"8":{"n":8,"verse":{"text":"Слово Твоё — светильник ноге моей.","ref":"Пс 118:105"},"intro":"Есть одна особенная Книга, которую написал сам Бог через людей. Сегодня узнаем, что такое Библия и почему её называют письмом от Бога.","story":["Библия — это самая главная и самая добрая Книга на свете. В ней Бог рассказывает нам о Себе, о Своей любви и о том, как жить хорошо и счастливо.","Библию писали много разных людей на протяжении очень долгого времени, но подсказывал им сам Бог. Поэтому Библию называют Божьим словом — как письмо от любящего Отца Своим детям.","В Библии много историй: о создании мира, о Ное и ковчеге, о добрых и смелых людях. Есть в ней и красивые песни-молитвы, и мудрые советы на каждый день.","Самая радостная весть Библии — что Бог любит нас и никогда не оставит. Слово Божье светит нам, как светильник во тьме, и помогает не сбиться с доброго пути.","Читать Библию — как разговаривать с Богом и слушать Его. Каждый раз она согревает сердце и делает нас чуть добрее и мудрее."],"golden":"Библия — это Божье письмо любви, которое освещает наш путь.","questions":["Почему Библию называют письмом от Бога?","Какая библейская история нравится тебе больше всего и почему?","Как слова из Библии могут помочь тебе в течение дня?"],"quiz":[{"q":"Что такое Библия?","opts":["Сборник сказок","Божье слово о Его любви","Книга загадок"],"answer":1},{"q":"Кто подсказывал людям, что писать в Библии?","opts":["Сам Бог","Никто","Другие книги"],"answer":0},{"q":"С чем сравнивается Божье слово в стихе урока?","opts":["С громом","С рекой","Со светильником для ног"],"answer":2}],"prayer":"Спасибо, Боже, за Твою Книгу — Библию. Помоги мне любить её и учиться из неё доброму. Аминь.","parentNote":"Откройте вместе детскую Библию и прочитайте короткий отрывок. Спросите ребёнка, что нового он узнал о Боге."},"9":{"n":9,"verse":{"text":"Возлюби Господа Бога твоего... и ближнего твоего, как самого себя.","ref":"Мф 22:37, 39"},"intro":"Зачем Бог дал людям правила? Сегодня узнаем, что заповеди — это не строгие запреты, а добрые правила любви.","story":["Однажды Бог дал людям особые правила — заповеди. Их было десять, и Бог дал их не для того, чтобы ругать нас, а чтобы нам было хорошо и безопасно жить.","Заповеди — как добрые указатели на дороге или ограда у обрыва. Они хранят нас от беды и учат жить в мире и любви друг с другом.","Бог просит любить Его больше всего и уважать Его имя. А ещё — почитать маму и папу, говорить правду, не брать чужого и не завидовать. Это делает наше сердце чистым.","Однажды Иисус сказал главное о заповедях: люби Бога всем сердцем и люби ближнего, как самого себя. Если в сердце есть любовь, то и все правила исполнить легко.","Заповеди — это правила любви. Когда мы их исполняем, мы становимся добрее, и вокруг нас, как от света маяка, становится теплее и спокойнее всем людям."],"golden":"Заповеди — это добрые правила любви к Богу и людям.","questions":["Почему заповеди можно назвать правилами любви, а не просто запретами?","Какая заповедь кажется тебе самой важной и почему?","Как ты можешь сегодня показать любовь к близкому человеку?"],"quiz":[{"q":"Зачем Бог дал людям заповеди?","opts":["Чтобы ругать нас","Чтобы нам было хорошо и безопасно жить","Просто так"],"answer":1},{"q":"С чем в уроке сравнили заповеди?","opts":["С добрыми указателями и оградой у обрыва","С тяжёлыми камнями","С холодной стеной"],"answer":0},{"q":"Что назвал главным Иисус?","opts":["Построить башню","Собрать много вещей","Любить Бога и ближнего"],"answer":2}],"prayer":"Боже, спасибо за Твои добрые правила. Помоги мне любить Тебя и людей вокруг каждый день. Аминь.","parentNote":"Обсудите, что правила Бога хранят нас, как ограда у обрыва. Спросите ребёнка, какое доброе дело он может сделать сегодня."},"10":{"n":10,"verse":{"text":"Прощайте, и прощены будете.","ref":"Лк 6:37"},"intro":"Что за тихий голосок внутри подсказывает нам, где добро, а где нет? Сегодня узнаем про совесть и про доброе чудо прощения.","story":["Внутри каждого человека Бог поместил тихий голосок — совесть. Она подсказывает, что хорошо, а что плохо. Когда мы делаем добро, на сердце светло, а когда обижаем кого-то — становится тяжело.","Совесть — как маленький маяк в сердце. Она не ругает нас, а мягко зовёт вернуться к добру. Слушать совесть — значит выбирать хорошее и честное.","Иногда мы всё же ошибаемся: поссоримся, скажем обидное слово. Но Бог дал нам чудесный выход — прощение. Можно сказать «прости» и попросить прощения у Бога и у людей.","Бог всегда прощает того, кто искренне раскаялся, и снимает тяжесть с сердца, будто и не было ошибки. А ещё Он просит и нас прощать других, чтобы в сердце не оставалось обиды.","Когда мы просим и даём прощение, в сердце снова становится тепло и светло. Прощение — как свежий ветер после дождя, оно всё делает чистым и новым."],"golden":"Совесть зовёт к добру, а прощение снова делает сердце светлым.","questions":["Что ты чувствуешь внутри, когда поступаешь хорошо, и когда обижаешь кого-то?","Почему просить прощения бывает трудно, но так важно?","Есть ли кто-то, кого тебе хотелось бы простить или у кого попросить прощения?"],"quiz":[{"q":"Что такое совесть?","opts":["Тихий голос внутри, что зовёт к добру","Игрушка","Громкий крик"],"answer":0},{"q":"Что Бог дал нам, чтобы исправить ошибку?","opts":["Наказание навсегда","Прощение","Ничего"],"answer":1},{"q":"О чём Бог просит нас, когда нас обидели?","opts":["Держать обиду","Отомстить","Прощать других"],"answer":2}],"prayer":"Боже, спасибо, что Ты прощаешь меня. Помоги мне слушать совесть и прощать других от сердца. Аминь.","parentNote":"Поговорите о том, что все ошибаются, но прощение возвращает мир в сердце. Помогите ребёнку сказать «прости», если есть повод."},"11":{"n":11,"verse":{"text":"За всё благодарите.","ref":"1 Фес 5:18"},"intro":"Умеешь ли ты замечать хорошее вокруг? Сегодня научимся говорить Богу спасибо и откроем секрет радостного сердца.","story":["Вокруг нас так много всего доброго: тёплое солнце, вкусный завтрак, мама рядом, друзья, любимая игрушка. Всё это — подарки от Бога, и за них можно сказать спасибо.","Благодарность — это когда мы замечаем хорошее и радуемся ему. Неблагодарное сердце всё время чем-то недовольно, а благодарное — радуется даже маленьким мелочам.","Богу очень приятно, когда мы говорим Ему спасибо, — так же, как маме приятно, когда её благодарят за заботу. И чем чаще мы благодарим, тем светлее становится у нас на душе.","Благодарить можно за большое и за маленькое: за целый день, за дождик, за то, что научился завязывать шнурки. Каждое «спасибо, Боже» делает сердце счастливее.","Благодарное сердце светится, как маяк, и согревает других. Попробуй каждый вечер вспоминать три хороших дела за день и благодарить за них Бога — и увидишь, как много вокруг добра."],"golden":"Благодарное сердце замечает добро и светится радостью.","questions":["За какие три вещи ты хочешь поблагодарить Бога сегодня?","Как ты думаешь, почему благодарным людям легче радоваться?","Кому из близких ты давно не говорил спасибо?"],"quiz":[{"q":"Что такое благодарность?","opts":["Умение замечать хорошее и радоваться ему","Скука","Жадность"],"answer":0},{"q":"Какое сердце всё время чем-то недовольно?","opts":["Благодарное","Неблагодарное","Спящее"],"answer":1},{"q":"Что советует урок делать каждый вечер?","opts":["Ссориться","Ничего не делать","Вспоминать и благодарить за хорошее"],"answer":2}],"prayer":"Спасибо, Боже, за все Твои подарки — большие и маленькие. Помоги мне видеть добро и благодарить каждый день. Аминь.","parentNote":"Заведите вечернюю традицию: вместе называйте три хорошие вещи за день. Это учит ребёнка замечать Божьи дары."},"12":{"n":12,"verse":{"text":"Благ Господь ко всем.","ref":"Пс 144:9"},"intro":"Мы прошли целый путь и узнали много о добром Боге. Давай вместе вспомним всё самое важное из нашего первого блока!","story":["Мы узнали, что Бог есть любовь: Он всегда рядом, знает нас по имени и светит нам, как маяк в тумане. А ещё Он создал прекрасный мир — небо, море, зверей и цветы — и подарил его нам.","Мы познакомились с первыми людьми, Адамом и Евой, и поняли, что Бог любит нас даже когда мы ошибаемся. Вспомнили доброго Ноя и ковчег, над которым Бог зажёг радугу как знак верности.","История вавилонской башни научила нас быть скромными и помнить Бога. Мы узнали, что молитва — это тёплый разговор с Богом, а ангелы — Его добрые посланники, что берегут нас.","Мы открыли Библию — Божье письмо любви — и заповеди, которые оказались добрыми правилами любви к Богу и людям. Поняли, что совесть зовёт к добру, а прощение делает сердце снова светлым.","И, наконец, мы научились благодарить Бога за большое и маленькое. Весь этот блок про одно главное: Бог добрый, Он любит тебя и всегда рядом. Пусть Его свет согревает твоё сердце!"],"golden":"Бог добрый, Он любит тебя и всегда рядом — вот главное, что мы узнали.","questions":["Какой урок из этого блока запомнился тебе больше всего и почему?","Что нового ты узнал о том, какой Бог?","Как то, что ты узнал о Боге, помогает тебе жить добрее?"],"quiz":[{"q":"Что Бог зажёг на небе после потопа как знак Своего обещания?","opts":["Звезду","Радугу","Молнию"],"answer":1},{"q":"Что такое молитва, о которой мы говорили?","opts":["Разговор с Богом","Игра","Песня без слов"],"answer":0},{"q":"Чем на самом деле оказались Божьи заповеди?","opts":["Строгими запретами","Скучными словами","Добрыми правилами любви"],"answer":2}],"prayer":"Спасибо, Боже, за всё, что мы узнали о Тебе. Ты добрый и любишь меня — помоги мне всегда быть рядом с Тобой. Аминь.","parentNote":"Вспомните вместе любимые истории блока и спросите, что ребёнок понял о характере Бога. Похвалите его за пройденный путь."},"13":{"n":13,"verse":{"text":"Аврам поверил Господу, и Он вменил ему это в праведность.","ref":"Быт 15:6"},"intro":"Жил однажды человек, который поверил Богу так крепко, что Бог назвал его Своим другом. Хочешь узнать, как это случилось?","story":["Давным-давно в далёкой стране жил Авраам. Однажды Бог сказал ему тихим, добрым голосом: «Оставь свой дом и иди в землю, которую Я тебе покажу». Авраам не знал дороги и не видел этой земли, но он доверился Богу и пошёл, как идут за светом маяка в тумане.","Авраам и его жена Сарра были уже совсем немолодыми, а детей у них не было. Однажды ночью Бог вывел Авраама под открытое небо и сказал: «Посмотри на звёзды. Сможешь ли ты их сосчитать? Столько будет у тебя потомков». Авраам поднял глаза и улыбнулся, ведь он поверил Богу.","Годы шли, а обещанного сына всё не было. Но Авраам продолжал верить, что Бог держит Своё слово. И правда — когда пришло время, у Авраама и Сарры родился долгожданный сынок, которого назвали Исаак, что значит «смех», ведь радости было через край.","За то, что Авраам всем сердцем доверял Богу и слушался Его, Бог назвал Авраама Своим другом. Не богатство и не сила сделали его особенным, а простая и крепкая вера.","Так Авраам стал отцом большого народа и другом Божьим. И всё потому, что однажды он просто сказал Богу: «Я Тебе верю»."],"golden":"Вера — это когда мы доверяем Богу, даже если ещё не видим всей дороги.","questions":["Как ты думаешь, было ли Аврааму страшно идти в неизвестную землю, и что помогло ему сделать шаг?","Что Бог показал Аврааму ночью и что это обещало?","А ты можешь вспомнить случай, когда тебе пришлось поверить, хотя ты ещё не всё понимал?"],"quiz":[{"q":"Что Бог велел Аврааму сделать?","opts":["Построить большой корабль","Оставить дом и идти в новую землю","Спрятаться в пещере"],"answer":1},{"q":"С чем Бог сравнил будущих потомков Авраама?","opts":["Со звёздами на небе","С камнями на дороге","С каплями дождя"],"answer":0},{"q":"Как звали сына, которого Бог подарил Аврааму и Сарре?","opts":["Иаков","Моисей","Исаак"],"answer":2}],"prayer":"Дорогой Боже, помоги мне доверять Тебе так же крепко, как Авраам, даже когда я не вижу всей дороги. Спасибо, что Ты всегда рядом. Аминь.","parentNote":"Поговорите с ребёнком о том, что вера — это доверие любящему Богу, а не отсутствие вопросов. Расскажите, как ваша семья училась доверять Богу в трудную минуту."},"14":{"n":14,"verse":{"text":"Я Господь, Бог Авраама, отца твоего, и Бог Исаака; не бойся, Я с тобою.","ref":"Быт 26:24"},"intro":"У Авраама вырос сын Исаак, а у Исаака — сыновья-близнецы. Их история полна ошибок, прощения и Божьей верности.","story":["Исаак вырос добрым и тихим человеком. Он молился Богу и доверял Ему, как когда-то его отец Авраам. Когда Исаак вырос, Бог подарил ему верную жену Ревекку, и вместе они любили Господа.","У Исаака и Ревекки родились два сына-близнеца: Исав и Иаков. Исав был старшим, любил охоту и поля, а Иаков был спокойнее и часто оставался дома. Братья были совсем разными, и не всегда между ними был мир.","Однажды Иаков поступил нечестно и получил обманом благословение, которое отец готовил для старшего брата. Исав очень обиделся, и Иакову пришлось надолго уйти из дома. Но даже в этой ошибке Бог не оставил Иакова.","По дороге Иаков заснул, положив под голову камень. И приснилась ему лестница до самого неба, а по ней ходили ангелы. Бог сказал ему сверху: «Не бойся, Я с тобою и сохраню тебя везде, куда ты пойдёшь». Иаков проснулся и понял: Бог рядом даже здесь, в пустыне.","Прошли годы, и Иаков вернулся домой. Он помирился с братом Исавом, они обнялись и плакали от радости. Так Бог показал, что Он верен и умеет превращать наши ошибки в добро."],"golden":"Бог остаётся верным нам, даже когда мы ошибаемся, и всегда зовёт нас к примирению.","questions":["Чем отличались братья Исав и Иаков друг от друга?","Что Иаков увидел во сне и что Бог ему пообещал?","Как ты думаешь, почему так важно было братьям помириться?"],"quiz":[{"q":"Как звали двух сыновей-близнецов Исаака?","opts":["Исав и Иаков","Каин и Авель","Пётр и Иоанн"],"answer":0},{"q":"Что Иаков увидел во сне в пустыне?","opts":["Большую рыбу","Лестницу до неба с ангелами","Горящий куст"],"answer":1},{"q":"Чем закончилась история братьев?","opts":["Они навсегда поссорились","Они уплыли за море","Они помирились и обнялись"],"answer":2}],"prayer":"Господи, спасибо, что Ты рядом даже тогда, когда я ошибаюсь. Помоги мне мириться с теми, кого я обидел, и прощать других. Аминь.","parentNote":"Используйте историю, чтобы мягко поговорить о примирении в семье между братьями и сёстрами. Подчеркните, что Бог любит нас и когда мы ошибаемся."},"15":{"n":15,"verse":{"text":"Вот, вы умышляли против меня зло; но Бог обратил это в добро.","ref":"Быт 50:20"},"intro":"У одного мальчика было двенадцать братьев и красивая разноцветная одежда. Его история — о том, как Бог хранит нас даже в самые трудные дни.","story":["Иосиф был одним из двенадцати братьев, и отец любил его особенно нежно. Он подарил Иосифу красивую разноцветную одежду. Братья увидели это и стали завидовать, ведь им казалось, что их любят меньше.","От зависти братья поступили очень плохо: они продали Иосифа купцам, которые увезли его далеко-далеко, в Египет. Иосифу было грустно и одиноко, но он не переставал доверять Богу, и Бог был с ним.","В Египте Иосиф трудился честно и оставался добрым, что бы ни случилось. Бог дал ему мудрость понимать сны, и однажды Иосиф объяснил сон самому царю — фараону. Он предупредил, что придёт большой голод, и научил, как запасти хлеб.","За мудрость фараон сделал Иосифа главным помощником во всём Египте. И когда голод пришёл, у Иосифа было много хлеба, чтобы накормить людей. Даже его братья пришли издалека, чтобы купить еды, и не узнали его.","Иосиф простил братьев и сказал им с любовью: «Вы хотели мне зла, а Бог обратил это в добро». Он обнял их, и вся семья снова была вместе. Так Бог хранил Иосифа на каждом шагу."],"golden":"Даже когда другие поступают с нами плохо, Бог может обратить всё в добро.","questions":["Почему братья стали завидовать Иосифу?","Как Иосиф вёл себя в Египте, когда ему было трудно?","Что ты чувствуешь, когда думаешь, что Иосиф простил своих братьев?"],"quiz":[{"q":"Какой подарок отец подарил Иосифу?","opts":["Разноцветную одежду","Золотую корону","Быстрого коня"],"answer":0},{"q":"Какой особый дар Бог дал Иосифу в Египте?","opts":["Он умел летать","Он понимал сны","Он был самым сильным"],"answer":1},{"q":"Как Иосиф поступил со своими братьями в конце?","opts":["Прогнал их навсегда","Наказал их","Простил и обнял их"],"answer":2}],"prayer":"Дорогой Боже, помоги мне прощать, как прощал Иосиф, и верить, что Ты можешь любую беду обратить в добро. Спасибо, что Ты всегда со мной. Аминь.","parentNote":"Обсудите с ребёнком зависть и прощение на простых примерах из жизни. Покажите, что честность и доброта важнее обиды."},"16":{"n":16,"verse":{"text":"Я буду при устах твоих и научу тебя, что тебе говорить.","ref":"Исх 4:12"},"intro":"Один маленький малыш плыл по реке в корзинке — и стал великим вождём. Как же так вышло?","story":["Давным-давно в Египте родился мальчик по имени Моисей. В то время было опасно, и мама очень хотела его спасти. Она сплела крепкую корзинку, положила туда сыночка и осторожно опустила корзинку на тихую реку среди камышей, доверив малыша Богу.","Корзинку нашла дочь фараона, египетская принцесса. Она увидела маленького Моисея, и её сердце наполнилось любовью. Принцесса взяла мальчика к себе, и он вырос во дворце, как царевич.","Когда Моисей вырос, он узнал, что его народ страдает в рабстве. Ему стало очень жаль людей, и он ушёл далеко в пустыню, где пас овец и много думал о Боге.","Однажды Моисей увидел удивительное: куст горел огнём, но не сгорал! Из куста Бог позвал его по имени: «Моисей, Моисей!» И Бог сказал: «Я посылаю тебя вывести Мой народ из рабства на свободу».","Моисей испугался и сказал: «Но я не умею красиво говорить». А Бог ответил с любовью: «Не бойся, Я буду с тобой и научу тебя, что говорить». И Моисей поверил Богу и пошёл исполнять Его поручение."],"golden":"Бог выбирает не самых сильных, а тех, кто готов Ему довериться, и Сам даёт им силы.","questions":["Как мама спасла маленького Моисея?","Что удивительного было в кусте, который увидел Моисей?","Что ты сказал бы Богу, если бы Он позвал тебя сделать что-то важное?"],"quiz":[{"q":"Куда мама положила маленького Моисея, чтобы спасти его?","opts":["В корзинку на реке","В большой сундук","На высокую гору"],"answer":0},{"q":"Что было необычного в кусте в пустыне?","opts":["Он был золотым","Он горел, но не сгорал","Он умел говорить сам"],"answer":1},{"q":"Что Бог ответил Моисею, когда тот испугался говорить?","opts":["«Найди себе другого»","«Тогда молчи»","«Не бойся, Я буду с тобой»"],"answer":2}],"prayer":"Господи, спасибо, что Ты выбираешь и помогаешь даже тем, кто чего-то боится. Будь со мной и научи меня делать доброе. Аминь.","parentNote":"Подчеркните ребёнку, что Бог использует обычных людей и даёт им силы. Поддержите ребёнка, если он чего-то боится: Бог помогает нам."},"17":{"n":17,"verse":{"text":"Не бойтесь, стойте — и увидите спасение Господне.","ref":"Исх 14:13"},"intro":"Целый народ шёл к свободе, а впереди — море. Что же сделал Бог? Слушай эту удивительную историю.","story":["Моисей пришёл к фараону и передал ему Божьи слова: «Отпусти Мой народ». Но фараон был упрямым и долго не хотел отпускать людей из рабства. Бог показал Свою силу, и наконец фараон разрешил народу уйти.","И вот большой народ Израиля вышел из Египта на свободу! Люди радовались и шли за Моисеем. А чтобы они не заблудились, Бог шёл впереди них: днём в виде облачного столба, а ночью — в виде огненного столба, как добрый маяк в темноте.","Но фараон передумал и погнался за народом со своим войском. Люди подошли к самому морю и остановились: впереди вода, а сзади — колесницы. Стало страшно. Но Моисей сказал спокойно: «Не бойтесь, стойте и увидите, как спасёт вас Господь».","Тогда Бог сотворил чудо. Моисей поднял руку над морем, и вода расступилась, открыв сухую дорогу прямо посреди волн! Народ прошёл по дну моря, а по бокам стояли стены воды. Бог берёг их на каждом шагу.","Когда все люди перешли на другой берег, море снова сомкнулось. Народ был спасён! Люди пели и благодарили Бога за то, что Он вывел их к свободе Своей крепкой рукой."],"golden":"Когда кажется, что выхода нет, Бог может открыть путь там, где мы его совсем не ждём.","questions":["Как Бог вёл народ днём и ночью, чтобы они не заблудились?","Что почувствовали люди, когда оказались между морем и войском?","Что помогает тебе не бояться, когда что-то кажется трудным?"],"quiz":[{"q":"Как Бог вёл народ ночью?","opts":["Огненным столбом","Яркой звездой","Пением птиц"],"answer":0},{"q":"Что сделал Бог, когда народ подошёл к морю?","opts":["Послал лодки","Расступил воду, открыв сухую дорогу","Построил мост"],"answer":1},{"q":"Что сказал Моисей испуганным людям у моря?","opts":["«Бегите скорее назад»","«Прыгайте в воду»","«Не бойтесь, увидите спасение Господне»"],"answer":2}],"prayer":"Дорогой Боже, спасибо, что Ты открываешь путь даже там, где кажется тупик. Помоги мне не бояться и доверять Тебе. Аминь.","parentNote":"Расскажите ребёнку, что Бог заботится о нас в трудностях и ведёт нас, как вёл народ. Вспомните вместе момент, когда Бог помог вашей семье."},"18":{"n":18,"verse":{"text":"Возлюби Господа Бога твоего всем сердцем твоим... и ближнего твоего, как самого себя.","ref":"Мф 22:37,39"},"intro":"Однажды Бог дал людям особые правила любви, написанные на камне. Эти правила помогают нам жить хорошо и сегодня.","story":["Народ Израиля шёл по пустыне и пришёл к высокой горе Синай. Бог позвал Моисея подняться на гору, чтобы поговорить с ним. Гора покрылась облаком, и там Бог дал Моисею особый подарок — правила жизни.","Эти правила называют Десятью заповедями. Бог написал их на двух каменных плитах. Это были не сложные законы, а добрые советы любящего Отца о том, как жить в мире с Богом и людьми.","Первые заповеди учат любить Бога: почитать только Его одного, беречь Его имя и посвящать Ему особый день отдыха. Ведь когда мы любим Бога, наше сердце становится спокойным и радостным.","Другие заповеди учат любить людей: почитать маму и папу, не обижать других, не брать чужое, не обманывать и не завидовать. Эти правила, как заботливая ограда, хранят нас и тех, кто рядом.","Позже Иисус объяснил всё коротко: люби Бога всем сердцем и люби ближнего, как самого себя. В этих словах — сердце всех заповедей. Так Бог показал нам самый добрый путь для жизни."],"golden":"Все Божьи заповеди учат одному — любить Бога и любить людей.","questions":["На чём Бог написал десять заповедей и кому Он их дал?","Чему учат заповеди о людях: как надо относиться к другим?","Какую заповедь тебе было бы легче всего исполнять, а какую — труднее?"],"quiz":[{"q":"На какой горе Бог дал Моисею заповеди?","opts":["На горе Синай","На горе Арарат","На Елеонской горе"],"answer":0},{"q":"Сколько заповедей дал Бог?","opts":["Три","Десять","Сто"],"answer":1},{"q":"Как Иисус кратко объяснил все заповеди?","opts":["Много работать","Быть самым главным","Любить Бога и любить ближнего"],"answer":2}],"prayer":"Господи, спасибо за Твои добрые правила. Помоги мне любить Тебя всем сердцем и быть добрым к людям рядом. Аминь.","parentNote":"Обсудите с ребёнком заповеди как проявление Божьей любви и заботы, а не строгих запретов. Приведите примеры из повседневной жизни семьи."},"19":{"n":19,"verse":{"text":"Будь твёрд и мужествен... ибо с тобою Господь Бог твой везде, куда ни пойдёшь.","ref":"Нав 1:9"},"intro":"Как можно взять большой город с крепкими стенами без единого удара? Бог показал Иисусу Навину удивительный способ.","story":["После Моисея вождём народа стал Иисус Навин — смелый и верный человек. Бог сказал ему: «Будь твёрд и мужествен, ведь Я всегда с тобой, куда бы ты ни пошёл». И Иисус Навин повёл народ дальше, в обещанную землю.","На пути стоял большой город Иерихон. Его окружали высокие крепкие стены, а ворота были плотно заперты. Люди могли бы испугаться, но Бог дал им совсем необычный план.","Бог сказал: пусть весь народ шесть дней тихо обходит город один раз в день. Впереди пусть идут священники и трубят в трубы. А на седьмой день нужно обойти город семь раз, громко затрубить и всем вместе радостно закричать.","Народ послушался Бога и делал всё в точности, хоть это и казалось необычным. Шесть дней они молча обходили город. Люди учились доверять Богу и слушаться Его.","И вот на седьмой день, после седьмого круга, зазвучали трубы, и весь народ радостно закричал. И тогда крепкие стены Иерихона рухнули! Не мечи и не тараны, а вера и послушание Богу открыли путь в город."],"golden":"С Богом даже самые крепкие стены не устоят, если мы верим и слушаемся Его.","questions":["Что Бог сказал Иисусу Навину, чтобы поддержать его смелость?","Каким необычным способом Бог велел взять город?","Легко ли слушаться, когда просьба кажется странной, и почему народ всё же послушался?"],"quiz":[{"q":"Кто стал вождём народа после Моисея?","opts":["Иисус Навин","Даниил","Соломон"],"answer":0},{"q":"Сколько раз народ обошёл город в седьмой день?","opts":["Один раз","Семь раз","Три раза"],"answer":1},{"q":"Что случилось со стенами Иерихона в конце?","opts":["Их разбили тараном","Их перелезли по лестницам","Они рухнули сами"],"answer":2}],"prayer":"Дорогой Боже, дай мне быть смелым и послушным, как Иисус Навин. Спасибо, что Ты всегда со мной, куда бы я ни пошёл. Аминь.","parentNote":"Поговорите о том, что послушание Богу иногда требует доверия, даже когда мы не всё понимаем. Похвалите ребёнка за смелость доверять."},"20":{"n":20,"verse":{"text":"Ты идёшь против меня с мечом... а я иду против тебя во имя Господа.","ref":"1 Цар 17:45"},"intro":"Маленький пастушок вышел против огромного воина — и победил. Всё потому, что рядом с ним был Бог.","story":["Давид был младшим в семье и пас овец в поле. Он любил играть на арфе и петь песни Богу. Давид был ещё юным, но у него было храброе сердце, ведь он крепко доверял Господу.","В то время народу Израиля угрожал великан по имени Голиаф. Он был очень большого роста и громко кричал, пугая всех воинов. Люди боялись выходить против него, и всем было тревожно.","И тогда маленький Давид сказал: «Я не боюсь, ведь со мной Бог». Он не взял тяжёлых доспехов. Он взял только пастушью пращу и пять гладких камешков из ручья, а главное — свою веру в Господа.","Давид смело сказал великану: «Ты идёшь на меня с мечом, а я иду во имя Господа». Он положил камень в пращу, раскрутил её и метнул. Камень попал точно, и великан упал на землю.","Так маленький пастушок победил огромного воина — не своей силой, а Божьей помощью. Народ радовался и благодарил Бога. А Давид на всю жизнь запомнил: не рост и не сила решают победу, а вера в Господа."],"golden":"С Богом даже самый маленький может справиться с самой большой трудностью.","questions":["Чем занимался Давид, пока был мальчиком?","Почему Давид не побоялся выйти против великана?","Что для тебя бывает похоже на «великана», и кто может помочь тебе с этим?"],"quiz":[{"q":"Кем был Давид, пока был мальчиком?","opts":["Пастухом","Рыбаком","Кузнецом"],"answer":0},{"q":"Что Давид взял с собой против Голиафа?","opts":["Большой меч и щит","Пращу и пять камешков","Копьё и коня"],"answer":1},{"q":"Благодаря чему Давид победил великана?","opts":["Своей огромной силе","Крепким доспехам","Помощи и вере в Бога"],"answer":2}],"prayer":"Господи, когда мне страшно перед чем-то большим, напомни, что Ты рядом. Дай мне храброе сердце, как у Давида. Аминь.","parentNote":"Мягко подайте образ великана — акцент на смелости веры, а не на страхе. Помогите ребёнку назвать свои «великаны» (страхи) и вместе помолитесь о них."},"21":{"n":21,"verse":{"text":"Даруй же рабу Твоему сердце разумное, чтобы... различать, что добро и что зло.","ref":"3 Цар 3:9"},"intro":"Если бы Бог предложил тебе любой подарок, что бы ты попросил? Царь Соломон попросил кое-что необычное.","story":["Давид вырос и стал царём, а после него царём стал его сын Соломон. Соломон был ещё молод, и ему предстояло управлять большим народом. Он понимал, что это очень трудное дело.","Однажды ночью Бог явился Соломону во сне и сказал: «Проси, что хочешь, и Я дам тебе». Соломон мог бы попросить богатство, долгую жизнь или победу над врагами. Но он попросил совсем другое.","Соломон сказал: «Дай мне мудрое сердце, чтобы я умел различать добро и зло и правильно управлять народом». Богу очень понравилась эта просьба, ведь Соломон подумал не о себе, а о людях.","Бог дал Соломону такую мудрость, какой не было ни у кого. А ещё Бог добавил ему и богатство, и почёт, о которых тот даже не просил. Люди приходили издалека, чтобы послушать мудрого царя.","Однажды к Соломону пришли две женщины, которые спорили об одном ребёнке. Соломон мудро придумал, как узнать, кто настоящая мама, — и все увидели, что Бог дал ему по-настоящему разумное сердце."],"golden":"Настоящая мудрость — это дар Божий, о котором стоит просить больше всего.","questions":["Что Бог предложил Соломону во сне?","Почему Богу так понравилась просьба Соломона?","Как ты думаешь, чем мудрость важнее богатства?"],"quiz":[{"q":"Чьим сыном был царь Соломон?","opts":["Давида","Моисея","Авраама"],"answer":0},{"q":"О чём Соломон попросил Бога?","opts":["О горах золота","О мудром сердце","О большом войске"],"answer":1},{"q":"Что Бог дал Соломону вдобавок к мудрости?","opts":["Только длинный меч","Ничего больше","Богатство и почёт"],"answer":2}],"prayer":"Дорогой Боже, дай мне мудрое сердце, чтобы отличать доброе от плохого и поступать правильно. Спасибо, что Ты слышишь мои просьбы. Аминь.","parentNote":"Обсудите с ребёнком, что важно просить у Бога правильных вещей. Помогите понять разницу между «хочу» и «что действительно полезно»."},"22":{"n":22,"verse":{"text":"Господь есть Бог, Господь есть Бог!","ref":"3 Цар 18:39"},"intro":"Один смелый пророк не побоялся напомнить целому народу, Кто есть настоящий Бог. Его звали Илия.","story":["Илия был пророком Божьим — человеком, который передавал людям Божьи слова. В то время многие забыли Бога и стали поклоняться выдуманным идолам. Но Илия оставался верным Господу и не боялся говорить правду.","Однажды Илия предложил всему народу проверку, чтобы люди увидели, Кто есть настоящий Бог. На горе поставили два жертвенника, и Илия сказал: «Пусть тот Бог, Который ответит огнём с неба, и есть истинный Бог».","Служители идолов долго кричали и звали своих богов, но небо молчало, ведь идолы не могут слышать. А потом настала очередь Илии. Он спокойно помолился Господу тихими, добрыми словами.","И тогда с неба сошёл огонь и принял жертву Илии! Народ увидел это и упал на колени, восклицая: «Господь есть Бог! Господь есть Бог!». Люди поняли, что живой Бог — только один.","А ещё Илия узнал, что Бог говорит не только огнём и громом. Однажды после сильного ветра и грома Бог заговорил с Илиёй тихим, нежным веянием. Так пророк понял: Бог рядом и в самом тихом шёпоте."],"golden":"Живой Бог всегда слышит нас и отвечает — иногда огнём, а иногда тихим, нежным голосом в сердце.","questions":["Кем был Илия и почему он был смелым?","Как народ узнал, Кто есть настоящий Бог?","Как ты думаешь, почему Бог иногда говорит с нами тихо?"],"quiz":[{"q":"Кем был Илия?","opts":["Пророком Божьим","Рыбаком","Царём Египта"],"answer":0},{"q":"Как Бог показал, что Он настоящий, на горе?","opts":["Послал сильный дождь","Послал огонь с неба на жертву","Открыл ворота города"],"answer":1},{"q":"Каким голосом Бог заговорил с Илиёй после ветра и грома?","opts":["Громким рёвом","Раскатом грома","Тихим, нежным веянием"],"answer":2}],"prayer":"Господи, помоги мне, как Илия, оставаться верным Тебе и слышать Твой тихий голос в моём сердце. Спасибо, что Ты живой и настоящий. Аминь.","parentNote":"Расскажите ребёнку, что Бог часто говорит тихо — через совесть, Слово, добрых людей. Поощряйте ребёнка прислушиваться к доброму в своём сердце."},"23":{"n":23,"verse":{"text":"Бог мой послал Ангела Своего и заградил пасть львам, и они не повредили мне.","ref":"Дан 6:22"},"intro":"Что делать, если за молитву тебя бросают в опасное место? Даниил показал, что с Богом бояться нечего.","story":["Даниил жил в далёкой стране и служил при дворе царя. Он был честным и мудрым, и все его уважали. А самое главное — Даниил каждый день молился Богу три раза, у открытого окна, и очень любил Господа.","Некоторые люди позавидовали Даниилу и придумали хитрый закон: целый месяц нельзя молиться никому, кроме царя. Но Даниил не испугался. Он, как всегда, встал у окна и спокойно помолился своему Богу.","За это Даниила по закону отвели ко рву, где были львы. Царь очень не хотел этого, ведь он любил Даниила, но закон уже был подписан. Он сказал Даниилу с надеждой: «Пусть твой Бог, Которому ты верно служишь, спасёт тебя».","Всю ночь Даниил провёл среди львов. Но случилось чудо: Бог послал Своего Ангела и закрыл львам пасти. Львы были смирными, как большие спокойные кошки, и не тронули Даниила. Он был в полной безопасности.","Наутро царь прибежал ко рву и позвал: «Даниил, спас ли тебя твой Бог?». И Даниил ответил: «Бог послал Ангела и заградил пасть львам!». Царь очень обрадовался и повелел всем почитать живого Бога Даниила."],"golden":"Когда мы верны Богу, Он бережёт нас даже в самых трудных обстоятельствах.","questions":["Что Даниил делал каждый день, несмотря на новый закон?","Как Бог защитил Даниила ночью?","Что помогает тебе поступать правильно, даже когда это трудно?"],"quiz":[{"q":"Сколько раз в день Даниил молился Богу?","opts":["Три раза","Один раз в неделю","Только по праздникам"],"answer":0},{"q":"Куда отвели Даниила за то, что он молился?","opts":["На высокую башню","Ко рву со львами","В далёкую пустыню"],"answer":1},{"q":"Как Бог защитил Даниила среди львов?","opts":["Погасил огонь","Открыл дверь темницы","Послал Ангела и заградил львам пасти"],"answer":2}],"prayer":"Дорогой Боже, помоги мне быть верным Тебе, как Даниил, и не бояться. Спасибо, что Ты бережёшь меня и днём, и ночью. Аминь.","parentNote":"Львов подавайте мягко: акцент на Божьей защите и верности Даниила, без пугающих деталей. Подчеркните силу привычки молиться каждый день."},"24":{"n":24,"verse":{"text":"И воззвал я в скорби моей к Господу... и Он услышал голос мой.","ref":"Ион 2:3"},"intro":"Один человек попробовал убежать от Бога на корабле. Но узнал, что Бог любит нас даже тогда, когда мы прячемся.","story":["Однажды Бог сказал пророку Ионе: «Иди в большой город Ниневию и скажи людям, чтобы они перестали делать зло». Но Иона не захотел идти. Он решил убежать от Бога и сел на корабль, который плыл совсем в другую сторону.","На море поднялась сильная буря, и корабль сильно качало. Иона понял, что убегать от Бога нельзя, и попросил моряков опустить его в воду, чтобы буря утихла. И как только это случилось, море успокоилось.","А Бог, любящий Иону, приготовил для него большую рыбу. Рыба бережно проглотила Иону, и он оказался внутри, живой и в безопасности. Три дня и три ночи Иона провёл в животе большой рыбы.","Там, в темноте, Иона стал молиться. Он сказал Богу: «В моей беде я воззвал к Тебе, и Ты услышал меня». Иона понял, как сильно любит его Бог, и решил больше не убегать. Тогда рыба вынесла его на сушу.","Иона пошёл в Ниневию и передал людям Божьи слова. И произошло чудо: весь город послушал и перестал делать зло. Бог простил их. Так Иона узнал, что у Бога доброе сердце и Он любит всех людей."],"golden":"От Бога нельзя убежать, потому что Его любовь находит нас везде и всегда даёт нам новый шанс.","questions":["Куда Бог посылал Иону и что тот решил сделать сначала?","Что Иона понял, пока молился внутри большой рыбы?","Бывало ли тебе трудно послушаться, и что помогло всё-таки поступить правильно?"],"quiz":[{"q":"Куда Бог велел Ионе пойти?","opts":["В город Ниневию","На гору Синай","В Египет"],"answer":0},{"q":"Что приготовил Бог, чтобы спасти Иону в море?","opts":["Лодку с парусом","Большую рыбу","Мост через воду"],"answer":1},{"q":"Что сделали жители Ниневии, услышав Иону?","opts":["Прогнали его","Не поверили ему","Послушали и перестали делать зло"],"answer":2}],"prayer":"Господи, спасибо, что Твоя любовь находит меня везде. Помоги мне слушаться Тебя и верить, что Ты всегда даёшь новый шанс. Аминь.","parentNote":"Обсудите с ребёнком, что Бог любит нас, даже когда мы ошибаемся или прячемся, и всегда готов простить. Подчеркните тему второго шанса."},"25":{"n":25,"verse":{"text":"ибо ныне родился вам в городе Давидовом Спаситель, Который есть Христос Господь","ref":"Лк 2:11"},"intro":"В тихую ночь, когда все спали, случилось самое большое чудо в мире. Родился Тот, Кого так долго ждала земля.","story":["В маленьком городке Вифлееме было очень много людей — все пришли, чтобы записаться по приказу царя. Мест в гостиницах не осталось совсем. Марии и Иосифу пришлось остановиться в хлеву, где живут ослики и овечки. Именно там, среди сена и тёплого дыхания животных, родился Младенец Иисус.","Мария бережно завернула Сына в пелёнки и положила Его в ясли — кормушку для скота. Кто бы мог подумать, что Спаситель мира придёт так тихо и скромно! Не во дворце, не в золотой колыбели, а в простом хлеву, чтобы быть ближе к каждому из нас.","А в поле неподалёку пастухи стерегли своё стадо. Вдруг перед ними явился Ангел, и всё вокруг засияло светом. «Не бойтесь! — сказал Ангел. — Я возвещаю вам великую радость: сегодня родился Спаситель!» И тут же множество Ангелов запели, прославляя Бога.","Пастухи поспешили в Вифлеем и нашли Младенца в яслях, как и сказал Ангел. Они поклонились Ему с радостью и потом рассказывали всем о том, что видели. А на небе загорелась особая звезда — знак того, что в мир пришёл Свет, который никогда не погаснет."],"golden":"Иисус пришёл в мир тихо и скромно, чтобы стать Спасителем для каждого — и для тебя тоже.","questions":["Почему Иисус родился в хлеву, а не во дворце?","Кому Ангелы первыми сообщили радостную весть?","Что ты чувствуешь, когда думаешь, что Иисус родился ради тебя?"],"quiz":[{"q":"В каком городе родился Иисус?","opts":["В Вифлееме","В Иерусалиме","В Назарете"],"answer":0},{"q":"Куда Мария положила Младенца Иисуса?","opts":["В золотую колыбель","В ясли (кормушку)","В большую кровать"],"answer":1},{"q":"Кто первым узнал о рождении Спасителя?","opts":["Цари","Учители","Пастухи"],"answer":2}],"prayer":"Дорогой Иисус, спасибо, что Ты пришёл в наш мир ради любви ко мне. Помоги мне всегда хранить радость Рождества в сердце.","parentNote":"Расскажите ребёнку, что Рождество — это прежде всего о любви Бога, а не о подарках. Зажгите вечером свечу как символ Света, пришедшего в мир."},"26":{"n":26,"verse":{"text":"Иисус же преуспевал в премудрости и возрасте и в любви у Бога и человеков","ref":"Лк 2:52"},"intro":"Каким был Иисус, когда был маленьким мальчиком? Давай заглянем в Его детство.","story":["После Рождества Иисус рос в маленьком городке Назарете вместе с Марией и Иосифом. Иосиф был плотником — он делал столы, двери и разные вещи из дерева. Наверное, маленький Иисус часто был рядом, наблюдал за работой и помогал отцу.","Иисус был обычным ребёнком: Он играл, учился, помогал по дому. Но Он рос особенным — послушным, добрым и внимательным к Богу. Каждый день Он становился мудрее и был любим и Богом, и людьми вокруг Него.","Когда Иисусу было двенадцать лет, вся семья пошла в Иерусалим на большой праздник. По дороге домой Мария и Иосиф вдруг заметили, что Иисуса нет рядом! Они очень встревожились и вернулись искать Его.","Через три дня они нашли Иисуса в храме. Он сидел среди учителей, слушал их и задавал такие мудрые вопросы, что все удивлялись. «Разве вы не знали, что Мне должно быть в доме Отца Моего?» — сказал Иисус. Уже тогда Он любил Бога всем сердцем."],"golden":"Иисус с детства любил Бога и рос в мудрости — и мы можем расти и учиться каждый день.","questions":["Кем работал Иосиф, и как Иисус мог ему помогать?","Где Мария и Иосиф нашли двенадцатилетнего Иисуса?","Что помогает тебе становиться добрее и мудрее каждый день?"],"quiz":[{"q":"В каком городе рос Иисус?","opts":["В Вифлееме","В Назарете","В Иерусалиме"],"answer":1},{"q":"Какой была профессия Иосифа?","opts":["Пастух","Рыбак","Плотник"],"answer":2},{"q":"Где нашли Иисуса, когда Ему было двенадцать лет?","opts":["В храме среди учителей","На рынке","У реки"],"answer":0}],"prayer":"Господь, помоги мне расти добрым, послушным и мудрым, как Иисус в детстве. Научи меня любить Тебя всем сердцем.","parentNote":"Поговорите с ребёнком о том, что Иисус тоже был ребёнком — учился и слушался. Это помогает детям почувствовать, что Он их понимает."},"27":{"n":27,"verse":{"text":"Сей есть Сын Мой возлюбленный, в Котором Мое благоволение","ref":"Мф 3:17"},"intro":"Однажды у реки Иордан произошло удивительное событие, когда открылось само небо.","story":["В пустыне жил особый человек — Иоанн Креститель. Он призывал людей менять свою жизнь к лучшему, поворачиваться сердцем к Богу. Тех, кто хотел начать новую, чистую жизнь, Иоанн крестил в реке Иордан.","И вот однажды к реке пришёл Сам Иисус. Он попросил Иоанна крестить Его. Иоанн удивился и сказал: «Это мне надо креститься у Тебя!» Но Иисус ответил, что так нужно исполнить Божью волю, и Иоанн послушался.","Когда Иисус вышел из воды, случилось чудо. Небо раскрылось, и Дух Божий сошёл на Иисуса, словно тихий белый голубь. Всё вокруг наполнилось светом и покоем.","И тогда раздался голос с неба — это говорил Сам Бог Отец: «Это Сын Мой возлюбленный, в Котором Моё благоволение». В этот миг открылось, как сильно Отец любит Своего Сына, и что Иисус пришёл исполнить великое дело."],"golden":"Бог Отец любит Своего Сына Иисуса — и через Иисуса Он любит и нас как Своих детей.","questions":["Кто крестил людей в реке Иордан?","Что произошло, когда Иисус вышел из воды?","Что сказал голос с неба об Иисусе?"],"quiz":[{"q":"Как звали человека, который крестил в Иордане?","opts":["Пётр","Иоанн Креститель","Иосиф"],"answer":1},{"q":"В виде кого сошёл Дух Божий на Иисуса?","opts":["В виде голубя","В виде орла","В виде ветра"],"answer":0},{"q":"Чей голос раздался с неба?","opts":["Голос Ангела","Голос Иоанна","Голос Бога Отца"],"answer":2}],"prayer":"Небесный Отец, спасибо, что Ты называешь меня Своим любимым ребёнком. Помоги мне жить так, чтобы радовать Тебя.","parentNote":"Объясните ребёнку, что крещение Иисуса показало Его любовь к Богу и послушание. Напомните, что Бог любит и вашего ребёнка."},"28":{"n":28,"verse":{"text":"И говорит им: идите за Мною, и Я сделаю вас ловцами человеков","ref":"Мф 4:19"},"intro":"Иисус не хотел идти по земле один. Он позвал друзей, которые пошли за Ним.","story":["Однажды Иисус шёл вдоль берега Галилейского озера. Там Он увидел двух братьев — Петра и Андрея. Они были рыбаками и как раз забрасывали свои сети в воду. Иисус посмотрел на них и сказал: «Идите за Мной, и Я сделаю вас ловцами человеков».","И произошло удивительное: Пётр и Андрей тут же оставили свои сети и пошли за Иисусом. Немного дальше Иисус позвал ещё двух братьев — Иакова и Иоанна. И они тоже, не раздумывая, последовали за Ним.","Так постепенно Иисус выбрал двенадцать учеников. Среди них были рыбаки, был сборщик налогов по имени Матфей и другие простые люди. Они не были богатыми или знаменитыми — но Иисус увидел их сердца.","Эти двенадцать учеников стали близкими друзьями Иисуса. Они ходили с Ним повсюду, слушали Его слова, видели Его чудеса и учились любить людей так, как любит Он. Позже они рассказали всему миру об Иисусе."],"golden":"Иисус зовёт за Собой обычных людей — и каждый из нас может стать Его другом и учеником.","questions":["Кем были Пётр и Андрей до того, как встретили Иисуса?","Что сделали ученики, когда Иисус их позвал?","Как ты думаешь, что значит быть учеником Иисуса сегодня?"],"quiz":[{"q":"Сколько учеников выбрал Иисус?","opts":["Семь","Двенадцать","Три"],"answer":1},{"q":"Кем работали Пётр и Андрей?","opts":["Рыбаками","Пастухами","Плотниками"],"answer":0},{"q":"Что сделали братья, услышав зов Иисуса?","opts":["Спрятались","Долго думали","Оставили сети и пошли за Ним"],"answer":2}],"prayer":"Иисус, спасибо, что Ты зовёшь меня быть Твоим другом. Помоги мне идти за Тобой и слушать Твои слова.","parentNote":"Расскажите ребёнку, что Иисус выбрал простых людей. Каждый ребёнок ценен для Бога независимо от способностей или достижений."},"29":{"n":29,"verse":{"text":"И удивлялся неверию их... И ходил по окрестным селениям и учил","ref":"Мк 6:6"},"intro":"Иисус делал то, чего не может ни один человек. Его чудеса показывали любовь Бога.","story":["Куда бы ни приходил Иисус, к Нему стекались люди. Многие были больными, грустными, потерявшими надежду. И Иисус помогал им: слепые начинали видеть, хромые — ходить, а больные становились здоровыми. Он делал это не для славы, а из любви к людям.","Однажды к Иисусу пришло очень много народа — целых пять тысяч человек! Они слушали Его весь день и проголодались. У одного мальчика было всего пять хлебов и две рыбки. Иисус взял эту еду, поблагодарил Бога — и её хватило на всех, да ещё и осталось двенадцать полных корзин!","А как-то раз ученики плыли на лодке, и вдруг началась сильная буря. Волны заливали лодку, и ученики очень испугались. Но Иисус сказал ветру и морю: «Умолкни, перестань!» — и сразу стало тихо. Ученики удивились: даже ветер и волны Его слушаются!","Иисус совершал чудеса, чтобы показать, что Бог заботится о нас во всём — и когда мы голодны, и когда болеем, и когда нам страшно. Каждое чудо было как маленькое окошко, через которое сияла Божья любовь."],"golden":"Чудеса Иисуса показывают, что Бог любит нас и заботится о нас в любой нужде.","questions":["Как Иисус накормил пять тысяч человек?","Что сделал Иисус, когда на море была буря?","Для чего Иисус совершал чудеса?"],"quiz":[{"q":"Сколько хлебов и рыбок было у мальчика?","opts":["Пять хлебов и две рыбки","Два хлеба и пять рыбок","Десять хлебов"],"answer":0},{"q":"Что сказал Иисус буре на море?","opts":["«Плывите быстрее»","«Умолкни, перестань»","«Ждите утра»"],"answer":1},{"q":"Зачем Иисус совершал чудеса?","opts":["Чтобы прославиться","Чтобы получить деньги","Чтобы показать любовь и заботу Бога"],"answer":2}],"prayer":"Господь Иисус, спасибо, что Ты заботишься обо мне во всём. Помоги мне доверять Тебе, даже когда мне страшно.","parentNote":"Подчеркните, что чудеса — это проявление Божьей любви, а не волшебство. Иисус помогал людям из сострадания."},"30":{"n":30,"verse":{"text":"возлюби ближнего твоего, как самого себя","ref":"Лк 10:27"},"intro":"Иисус рассказал историю о том, кто такой настоящий друг и добрый человек.","story":["Однажды один человек спросил Иисуса: «А кто мой ближний, кого я должен любить?» И Иисус рассказал ему историю. Один путник шёл по дороге, и вдруг на него напали разбойники. Они отобрали всё, избили его и ушли, оставив бедного человека лежать на дороге.","Мимо проходил священник. Он увидел раненого, но прошёл мимо, ничего не сделав. Потом мимо прошёл ещё один важный человек. Он тоже посмотрел — и тоже прошёл дальше. Никто не захотел остановиться и помочь.","И вот по дороге ехал самарянин — человек из народа, который тогда не дружил с другими. Но у него было доброе сердце. Он увидел раненого, и ему стало жалко его. Самарянин перевязал ему раны, посадил на своего осла и отвёз в гостиницу.","Там он ухаживал за раненым, а уезжая, дал хозяину денег и попросил позаботиться о нём. Иисус спросил: «Кто же был настоящим ближним?» Ответ прост: тот, кто проявил милосердие. И Иисус сказал: «Иди, и ты поступай так же»."],"golden":"Настоящий ближний — это тот, кто помогает другому с добрым сердцем, не глядя, кто он.","questions":["Почему священник и другой человек не помогли раненому?","Что сделал добрый самарянин для пострадавшего?","Кому ты можешь помочь сегодня, как добрый самарянин?"],"quiz":[{"q":"Что случилось с путником на дороге?","opts":["Он заблудился","На него напали разбойники","Он уснул"],"answer":1},{"q":"Кто остановился и помог раненому?","opts":["Самарянин","Священник","Богатый купец"],"answer":0},{"q":"Чему учит эта притча?","opts":["Быстро ходить","Копить деньги","Помогать ближнему с добрым сердцем"],"answer":2}],"prayer":"Иисус, дай мне доброе сердце, чтобы я замечал тех, кому нужна помощь, и не проходил мимо.","parentNote":"Спросите ребёнка, кому он мог бы помочь на этой неделе. Милосердие лучше всего познаётся на практике."},"31":{"n":31,"verse":{"text":"ибо этот сын мой был мертв и ожил, пропадал и нашелся","ref":"Лк 15:24"},"intro":"Эта история — о папе, который любит своего ребёнка так сильно, что всегда ждёт его.","story":["У одного отца было два сына. Младший сын однажды сказал: «Отец, дай мне мою часть богатства, я хочу уйти». Отец с грустью отпустил его. Сын ушёл далеко в чужую страну и там растратил все деньги на пустые развлечения.","Скоро наступили трудные времена. Денег не осталось, друзья исчезли, и сын начал голодать. Ему пришлось пасти свиней, и он был так голоден, что готов был есть их корм. Тогда он вспомнил дом отца, где даже работникам жилось хорошо.","«Пойду к отцу и скажу: я согрешил, я недостоин быть твоим сыном, возьми меня хотя бы работником», — решил он и отправился домой. А отец всё это время ждал и высматривал сына на дороге. Увидев его издалека, отец побежал навстречу, обнял и расцеловал его.","Отец не стал ругать сына. Он так обрадовался, что устроил большой праздник: «Мой сын был потерян и нашёлся!» Так и Бог, наш Небесный Отец, всегда ждёт нас и с радостью прощает, когда мы возвращаемся к Нему."],"golden":"Бог, как любящий Отец, всегда ждёт нас и радостно прощает, когда мы возвращаемся к Нему.","questions":["Почему младшему сыну стало плохо в чужой стране?","Как отец встретил вернувшегося сына?","Как эта история показывает любовь Бога к нам?"],"quiz":[{"q":"Что сделал младший сын с деньгами отца?","opts":["Растратил их вдали от дома","Спрятал их","Отдал бедным"],"answer":0},{"q":"Как отец поступил, увидев вернувшегося сына?","opts":["Прогнал его","Побежал навстречу и обнял","Сделал вид, что не заметил"],"answer":1},{"q":"Чему учит притча о блудном сыне?","opts":["Копить богатство","Уходить из дома","Бог всегда прощает и ждёт нас"],"answer":2}],"prayer":"Небесный Отец, спасибо, что Ты всегда ждёшь меня и прощаешь. Помоги мне возвращаться к Тебе, когда я ошибаюсь.","parentNote":"Эта притча — о безусловной любви и прощении. Заверьте ребёнка, что дома его всегда любят и ждут, что бы ни случилось."},"32":{"n":32,"verse":{"text":"Вы свет мира. Так да светит свет ваш пред людьми","ref":"Мф 5:14,16"},"intro":"Однажды Иисус поднялся на гору и рассказал людям, как жить счастливо по-настоящему.","story":["Вокруг Иисуса собралось множество людей, и Он поднялся на гору, чтобы всем было хорошо слышно. Там Он начал учить их самым важным вещам. Эту речь запомнили навсегда — её называют Нагорной проповедью.","Иисус говорил удивительные слова: счастливы кроткие, счастливы милостивые, счастливы те, у кого чистое сердце. Он учил, что настоящее счастье — не в богатстве, а в добром сердце, которое любит Бога и людей.","Иисус сказал людям: «Вы — свет мира». Как маленькая свеча освещает всю комнату, так и добрые дела человека светят другим людям. Он призывал не прятать свой свет, а светить, чтобы люди видели добро и радовались.","А ещё Иисус научил всех особой молитве — «Отче наш». В ней мы называем Бога Отцом, просим у Него хлеба на каждый день, прощения и помощи. Иисус учил прощать других, не тревожиться о завтрашнем дне и доверять Богу, Который заботится даже о птицах и цветах."],"golden":"Иисус учит нас быть светом для других — светить добротой, любовью и добрыми делами.","questions":["Почему эту речь Иисуса называют Нагорной проповедью?","Что значит быть «светом мира»?","Какой молитве Иисус научил людей?"],"quiz":[{"q":"Где Иисус произнёс эту знаменитую проповедь?","opts":["На горе","В лодке","В храме"],"answer":0},{"q":"Какой молитве научил Иисус?","opts":["Молитве о дожде","Молитве «Отче наш»","Молитве перед сном"],"answer":1},{"q":"Кем Иисус назвал Своих слушателей?","opts":["Царями земли","Строителями","Светом мира"],"answer":2}],"prayer":"Господь, помоги мне быть маленьким светом доброты в этом мире и научи меня молиться Тебе с доверием.","parentNote":"Выучите вместе с ребёнком молитву «Отче наш». Поговорите о том, как простые добрые дела могут «светить» окружающим."},"33":{"n":33,"verse":{"text":"осанна Сыну Давидову! благословен Грядущий во имя Господне!","ref":"Мф 21:9"},"intro":"Иисус въезжал в большой город, и люди встречали Его как долгожданного Царя.","story":["Приближался большой праздник, и Иисус направлялся в Иерусалим. Он попросил учеников привести Ему молодого ослика. На осликах в те времена въезжали цари, которые приходили с миром, а не с войной. Иисус сел на ослика и поехал к городу.","Когда люди узнали, что Иисус идёт, они очень обрадовались. Многие сняли свои одежды и постелили их на дорогу, как красную дорожку для Царя. Другие срезали ветви пальм и махали ими в воздухе.","Толпа радостно кричала: «Осанна! Благословен Грядущий во имя Господне!» Слово «осанна» значит «спаси нас». Люди славили Иисуса, взрослые и дети пели от радости, и весь город наполнился ликованием.","Иисус въехал в Иерусалим тихо и кротко, на простом ослике, а не на боевом коне. Он пришёл не воевать, а принести людям мир, любовь и спасение. Это был особенный день, когда народ встречал своего Царя мира."],"golden":"Иисус — кроткий Царь мира, Который приходит с любовью, и Его радостно встречать в своём сердце.","questions":["На ком Иисус въехал в Иерусалим и почему?","Что люди стелили на дорогу и чем махали?","Что означает слово «осанна»?"],"quiz":[{"q":"На ком Иисус въехал в Иерусалим?","opts":["На молодом ослике","На коне","На колеснице"],"answer":0},{"q":"Чем люди махали, встречая Иисуса?","opts":["Флагами","Пальмовыми ветвями","Платками"],"answer":1},{"q":"Что означает слово «осанна»?","opts":["«Прощай»","«Добро пожаловать»","«Спаси нас»"],"answer":2}],"prayer":"Иисус, Ты — мой добрый Царь. Я хочу встречать Тебя в своём сердце с радостью и петь Тебе «осанна».","parentNote":"Расскажите, что Иисус — Царь мира и любви. Можно вместе сделать бумажную пальмовую ветвь в память об этом дне."},"34":{"n":34,"verse":{"text":"сие есть тело Мое, которое за вас предается; сие творите в Мое воспоминание","ref":"Лк 22:19"},"intro":"В тихий вечер Иисус собрал друзей за одним столом, чтобы сказать им что-то важное.","story":["Наступил вечер большого праздника, и Иисус захотел провести его вместе со Своими двенадцатью учениками. Они собрались в уютной верхней комнате, где был приготовлен ужин. Этот ужин мы называем Тайной вечерей.","Перед ужином Иисус сделал удивительную вещь. Он взял полотенце, налил воды и начал мыть ноги Своим ученикам — так, как делал самый скромный слуга. Ученики были поражены. Иисус хотел показать им, что настоящая любовь — это служить друг другу с добротой.","Во время ужина Иисус взял хлеб, поблагодарил Бога, разломил его и раздал ученикам: «Это Моё тело, которое отдаётся за вас». Потом Он взял чашу и сказал, что скоро отдаст Себя из любви ко всем людям. «Делайте это в память обо Мне», — попросил Он.","Иисус дал ученикам новую заповедь: «Любите друг друга, как Я возлюбил вас». Это был тёплый и важный вечер. Иисус знал, что впереди трудное время, но Он был полон любви и хотел, чтобы Его друзья всегда помнили о ней."],"golden":"Иисус учит нас любить и служить друг другу, как Он служил Своим ученикам.","questions":["Почему Иисус мыл ноги Своим ученикам?","Что Иисус сделал с хлебом на Тайной вечере?","Какую новую заповедь дал Иисус ученикам?"],"quiz":[{"q":"Как называется последний ужин Иисуса с учениками?","opts":["Тайная вечеря","Праздничный пир","Утренняя трапеза"],"answer":0},{"q":"Что необычного сделал Иисус перед ужином?","opts":["Спел песню","Вымыл ноги ученикам","Раздал подарки"],"answer":1},{"q":"Какую заповедь дал Иисус на Тайной вечере?","opts":["Много трудиться","Копить хлеб","Любить друг друга"],"answer":2}],"prayer":"Господь Иисус, спасибо за Твою великую любовь. Научи меня любить и помогать другим, как это делал Ты.","parentNote":"Обсудите, что Иисус показал любовь через служение. Предложите ребёнку сделать что-то доброе для члена семьи."},"35":{"n":35,"verse":{"text":"Его нет здесь: Он воскрес, как сказал","ref":"Мф 28:6"},"intro":"Это самая грустная и одновременно самая радостная история в мире — история о любви, которая победила.","story":["Иисус так сильно любил людей, что был готов отдать за них всё. Злые люди не поняли Его любви, и Иисуса распяли на кресте. Его друзья очень плакали и грустили. Казалось, что случилось самое печальное. Но Иисус знал, что это не конец, а начало чего-то прекрасного.","Тело Иисуса положили в пещеру-гробницу и закрыли вход большим тяжёлым камнем. Была тихая суббота, и всё вокруг словно замерло в ожидании. Друзья Иисуса ждали, храня в сердце любовь к Нему, хотя им было очень грустно.","И вот рано утром в воскресенье женщины пришли к гробнице — и увидели чудо! Тяжёлый камень был отвален, а гробница пуста. Сияющий Ангел сказал им: «Не бойтесь! Его нет здесь: Он воскрес, как сказал!» Иисус был жив!","Радость наполнила сердца всех друзей Иисуса. Смерть не смогла удержать Его, потому что Божья любовь сильнее всего на свете. Это и есть Пасха — праздник победы жизни, света и любви. Иисус живёт, и Он дарит эту радостную надежду каждому из нас."],"golden":"Иисус воскрес — Божья любовь сильнее смерти, и Он дарит нам радость и надежду навсегда.","questions":["Почему Пасха — это радостный праздник?","Что увидели женщины, когда пришли к гробнице утром?","Что сказал Ангел женщинам об Иисусе?"],"quiz":[{"q":"Что закрывало вход в гробницу Иисуса?","opts":["Большой камень","Деревянная дверь","Занавес"],"answer":0},{"q":"В какой день недели Иисус воскрес?","opts":["В субботу","В воскресенье","В пятницу"],"answer":1},{"q":"Что сказал Ангел женщинам?","opts":["«Ждите здесь»","«Идите домой»","«Он воскрес, как сказал»"],"answer":2}],"prayer":"Иисус, спасибо, что Ты живой и Твоя любовь сильнее всего. Наполни моё сердце пасхальной радостью и надеждой.","parentNote":"Подавайте тему креста бережно, делая акцент на любви и радости Воскресения. Пасха — праздник надежды и победы жизни."},"36":{"n":36,"verse":{"text":"примете силу, когда сойдет на вас Дух Святый... и будете Мне свидетелями","ref":"Деян 1:8"},"intro":"Перед тем как вернуться к Отцу на небо, Иисус оставил друзьям обещание и большое дело.","story":["После Воскресения Иисус ещё много дней был со Своими учениками. Он утешал их, учил и радовал их сердца. А потом наступил день, когда Иисусу нужно было вернуться к Небесному Отцу. Он вывел учеников на гору и благословил их.","Иисус дал ученикам важное поручение: «Идите и расскажите всем людям на земле обо Мне и о Божьей любви». А ещё Он обещал: «Я всегда с вами, во все дни». И затем на глазах учеников Иисус вознёсся на небо — это называется Вознесение.","Ученики ждали, как обещал Иисус, и молились вместе. И вот в день праздника случилось чудо: с неба пришёл Дух Святой, словно шум ветра и языки огня над каждым из них. Сердца учеников наполнились силой, радостью и смелостью.","Теперь ученики уже не боялись. Они смело выходили и рассказывали людям об Иисусе, и в тот день к ним присоединилось множество новых верующих. Так родилась Церковь — большая семья тех, кто любит Иисуса. И эта семья растёт по всему миру до сих пор."],"golden":"Иисус всегда с нами, и Дух Святой даёт нам силу и радость рассказывать другим о Божьей любви.","questions":["Какое поручение дал Иисус ученикам перед Вознесением?","Что произошло, когда пришёл Дух Святой?","Что такое Церковь?"],"quiz":[{"q":"Как называется возвращение Иисуса на небо?","opts":["Вознесение","Рождество","Крещение"],"answer":0},{"q":"Как пришёл Дух Святой к ученикам?","opts":["В виде дождя","Словно ветер и языки огня","В виде звезды"],"answer":1},{"q":"Что родилось, когда ученики стали рассказывать об Иисусе?","opts":["Новый город","Новая школа","Церковь — семья верующих"],"answer":2}],"prayer":"Господь, спасибо, что Ты всегда со мной. Наполни меня Твоей силой и радостью, чтобы я мог рассказывать другим о Твоей любви.","parentNote":"Объясните, что Церковь — это не только здание, а большая семья людей, любящих Бога. Ребёнок — её важная часть."}};
